// reviewFileNodeProblems は YAML のノードを様式に沿って歩き、decode 後の値では見えない
// 問題を報告する — 未知のキー、列の null 要素、スカラーの型。
//
// decode 後の値だけを見ると、yaml.v3 が黙って行う変換の向こう側は見えない (実測:
// null 要素は列から落ち、数値・真偽値は文字列の欄に文字列として入り、小数は int に
// 切り詰められた)。様式の検査は「書かれたとおりか」を見るものなので、変換の前の
// ノードで見る。attrs の中は見ない (パススルー)。問題が見つかっても走査を続ける。
func reviewFileNodeProblems(f string, n *yaml.Node) []string {
	var problems []string
	add := func(line int, format string, args ...any) {
		problems = append(problems, fmt.Sprintf("%s:%d: ", f, line)+fmt.Sprintf(format, args...))
	}
	isNull := func(v *yaml.Node) bool { return v.Kind == yaml.ScalarNode && v.Tag == "!!null" }
	// 文字列の欄。引用符の無い数値・真偽値は !!int / !!bool に解決されて黙って文字列に
	// なるので、書かれたとおりに読まれることを保証するために !!str を要求する。
	// date は形 (YYYY-MM-DD) を意味検査が見るので、ここでは型を見ない (引用符の無い
	// 日付は !!timestamp に解決され、文字列として正しく読める)。
	requireStr := func(v *yaml.Node, key string) {
		if v.Kind == yaml.ScalarNode && v.Tag != "!!str" && !isNull(v) {
			add(v.Line, "%s は文字列で書く (引用符の無い %s は %s として読まれ、書かれたとおりに残らない)", key, v.Value, v.Tag)
		}
	}
	// 整数の欄。小数は int に切り詰められ、文字列は decode で失敗するが文言が読めない。
	// 値は yaml.v3 と同じ規則で読む — !!int に解決される表記には 16 進・8 進・2 進・
	// 桁区切り (1_0) が含まれ、10 進だけを読む strconv.Atoi では読めない。読めない値を
	// 黙って通すと、-0x1 のような負の line が「問題なし」で抜ける (実測)。読めなければ
	// 報告する — 読めないものを問題なしにしない。
	requireInt := func(v *yaml.Node, key string, min int) {
		if v.Kind != yaml.ScalarNode || isNull(v) {
			return
		}
		if v.Tag != "!!int" {
			add(v.Line, "%s は整数で書く: %q (%s)", key, v.Value, v.Tag)
			return
		}
		i, err := strconv.ParseInt(strings.ReplaceAll(v.Value, "_", ""), 0, 64)
		if err != nil {
			add(v.Line, "%s を整数として読めません: %q (10 進で書く)", key, v.Value)
			return
		}
		if i < int64(min) {
			add(v.Line, "%s は %d 以上の整数にする: %d", key, min, i)
		}
	}
	// 別名 (アンカーへの参照)。様式は別名を使わない形なので、attrs の外に現れたら
	// 「様式に無い書き方」として報告する。別名を辿って型や未知キーを検査する案は
	// 採らない — 辿れば通る書き方を増やすことになり、様式が定める形から離れる。
	isAlias := func(v *yaml.Node, what string) bool {
		if v.Kind != yaml.AliasNode {
			return false
		}
		add(v.Line, "%s に別名 (*%s) は使えません (値をそのまま書く。attrs の外で別名を使うと型と未知キーの検査が届かない)", what, v.Value)
		return true
	}
	strKeys := map[string]bool{"skill": true, "model": true, "level": true, "run_id": true,
		"scope": true, "base": true, "head": true, "file": true, "summary": true, "evidence": true}

	var walkMap func(n *yaml.Node, kind string)
	walkMap = func(n *yaml.Node, kind string) {
		if n == nil || n.Kind != yaml.MappingNode {
			return
		}
		allowed := reviewFileAllowedKeys[kind]
		for i := 0; i+1 < len(n.Content); i += 2 {
			k, v := n.Content[i], n.Content[i+1]
			if !allowed[k.Value] {
				add(k.Line, "%sに未知のキー %q。様式に無いキーは attrs へ入れる (修正を記録するキーなら、レビューが報告のみで走っていない印)", kind, k.Value)
				continue
			}
			if k.Value != "attrs" && isAlias(v, k.Value) {
				continue
			}
			switch {
			case strKeys[k.Value]:
				requireStr(v, k.Value)
			case k.Value == "id":
				requireInt(v, "id", 1)
			case k.Value == "line":
				// 不明なら省略する欄。0 は省略と区別できず、記録から行番号が黙って消える。
				requireInt(v, "line", 1)
			case k.Value == "findings" && v.Kind == yaml.SequenceNode:
				for j, item := range v.Content {
					if isNull(item) {
						add(item.Line, "findings[%d] に中身がありません (書きかけの要素は列から落ちて「無い」と同じに読まれる)", j)
						continue
					}
					if isAlias(item, fmt.Sprintf("findings[%d]", j)) {
						continue
					}
					walkMap(item, "指摘")
				}
			case k.Value == "residual" && v.Kind == yaml.SequenceNode:
				for j, item := range v.Content {
					if isNull(item) {
						add(item.Line, "residual[%d] に中身がありません (1 行の要旨を書くか要素を消す)", j)
						continue
					}
					if isAlias(item, fmt.Sprintf("residual[%d]", j)) {
						continue
					}
					requireStr(item, fmt.Sprintf("residual[%d]", j))
				}
			}
		}
	}
	walkMap(n, "トップレベル")
	return problems

