	"サマリの再生成手段として案内する文字列 (エラー文と生成サマリの 1 行目に入る)。"+
		"-install-wrapper で省略すると、-current-dir から見たラッパーの相対パスで組み立てる")
reviewFilePath := fs.String("review-file", "",
	"記録の代わりに、上流レビューが書き出したレビュー結果ファイル (YAML) の様式を検査する。相対パスなら -current-dir も要る")
writeJudgmentFlow := fs.Bool("write-judgment-flow", false,
	"検査せず、判定フローの図を決定表と遷移表から生成して正本 (-judgment-flow か CLAUDE_PLUGIN_ROOT で決まる) に書き出す")
if err := fs.Parse(args); err != nil {
	return err
}

// 明示的に渡されたフラグを拾う。既定値との一致では判定しない — 利用者が
// 既定と同じ値を明示的に渡すことがあり、そのとき「指定していない」と誤って
// 扱うと、不在を報告すべき経路が黙って通る。flag.Visit は実際に指定された
// フラグだけを回すので、意思表示の有無をそのまま読める。
explicit := map[string]bool{}
fs.Visit(func(f *flag.Flag) { explicit[f.Name] = true })

// 経路どうしの衝突は、パスの規則より前に見る。-install-wrapper と
// -write-summary=true は「何を書き出すか」が食い違うので、黙って片方を
// 無視すると「指定したのに効かない」を作る。弾くのは「何かを要求したとき」
// だけ — -write-summary=false は「生成サマリは要らない」= -install-wrapper の
// 既定の挙動そのものを頼んでいるだけで、拒否する理由が無い。flag.Visit は
// 値を見ずに「指定された」と報告するので、値の側も見る。
if explicit["install-wrapper"] && explicit["write-summary"] && *writeSummary {
	return fmt.Errorf("-write-summary は %w (生成の経路では使われません)", errFlagUnusedWithInstallWrapper)
}
// -review-file は「記録の代わりにレビュー結果ファイルを検査する」経路で、
// 書き出しの 2 経路とは何をするかが食い違う。同じ理由で弾く。
if explicit["review-file"] {
	if explicit["install-wrapper"] {
		return fmt.Errorf("-install-wrapper は %w (レビュー結果の検査では使われません)", errFlagUnusedWithReviewFile)
	}
	if explicit["write-summary"] && *writeSummary {
		return fmt.Errorf("-write-summary は %w (レビュー結果の検査では使われません)", errFlagUnusedWithReviewFile)
	}
}
// -write-judgment-flow は「判定フローの図を書き出す」経路で、他の書き出し・検査の
// 経路とは何をするかが食い違う。同じ理由で弾く。
if explicit["write-judgment-flow"] && *writeJudgmentFlow {
	for _, name := range []string{"install-wrapper", "review-file"} {
		if explicit[name] {
			return fmt.Errorf("-%s は %w (判定フローの図の生成では使われません)", name, errFlagUnusedWithWriteJudgmentFlow)
		}
	}
	if explicit["write-summary"] && *writeSummary {
		return fmt.Errorf("-write-summary は %w (判定フローの図の生成では使われません)", errFlagUnusedWithWriteJudgmentFlow)
	}
}

// 空白だけの -summary-command は弾く — 通すと「再生成する手段は空欄です」と
// 案内することになり、指定しないより悪い。値そのものの決定は、パスの規則と
// 一緒に resolveInputs で行う (案内はパスの形をした値なので、同じ規則に乗せる)。
if explicit["summary-command"] && isBlankPath(*summaryCmd) {
	return fmt.Errorf("-summary-command に%w", errEmptySummaryCommand)
}

// パスの規則は、経路 (検査 / -write-summary / -install-wrapper) で分岐する前に
// 1 か所で当てる。経路ごとに書くと、規則を 1 つ足すたびに他の経路へ書き忘れ、
// 同じ入力に経路ごとに違う契約ができる (このブランチのレビューで、その型の
// 指摘が回を重ねて続いた)。ここを通った後の経路は、解決済みの絶対パスを
// 受け取るだけで、パスを検査しない。
in, err := resolveInputs(pathInputs{
	recordDir:      *recordDir,
	currentDir:     *currentDir,
	judgmentFlow:   *flowPath,
	installWrapper: *installWrapperPath,
	reviewFile:     *reviewFilePath,
	summaryCommand: *summaryCmd,
	explicit:       explicit,
})
if err != nil {
	return err
}

// 案内の文言も、経路の分岐より前に一度だけ据える。検査 (エラー文) と
// -write-summary (生成サマリの 1 行目) と -install-wrapper (焼き込み) が
// 同じ値を読むので、経路ごとに渡すと片方だけ違う案内を出す組み合わせができる。
summaryCommand = in.summaryCommand

	// 明示した在り処の不在は、経路を問わず「指定したのに検査できない」なので
	// ここで止める。置き場と判定フローの両方が無いときは 1 回の実行で両方を
	// 報告する — 片方で即 return すると、片方を直して再実行するまで
	// もう一方も壊れていることを知れない。
	if problems := missingPathProblems(in); len(problems) > 0 {
		for _, p := range problems {
			fmt.Fprintln(os.Stderr, "  - "+p)
		}
		return fmt.Errorf("triagecheck: %d 件の問題が見つかりました: %w", len(problems), errPathMissing)
	}

	// path.Clean で表記の揺れ (".", "./rec", "rec//") を畳む。照合は
	// inReviewTriageDir が両辺を clean して行うので、ここでの末尾のスラッシュは
	// エラーメッセージの見た目のためだけに付ける。
	reviewTriageDir = path.Clean(filepath.ToSlash(in.recordDir)) + "/"
	if in.judgmentFlow != "" {
		judgmentFlowPath = in.judgmentFlow
	}

	// 以降は経路ごとの処理。パスは上で解決済みなので、どの経路も値を検査しない。
	if in.installWrapper != "" {
		return installWrapper(in.installWrapper, in.recordDir, in.embedJudgmentFlow, in.summaryCommand)
	}
	if in.reviewFile != "" {
		// 不在は上で報告済み。読めないのは権限・I/O のエラーだけ。
		data, err := os.ReadFile(in.reviewFile)
		if err != nil {
			return fmt.Errorf("%s: レビュー結果の読み込みに失敗しました: %w", in.reviewFile, err)
		}
		if problems := reviewFileProblems(in.reviewFile, data); len(problems) > 0 {
			for _, p := range problems {
				fmt.Fprintln(os.Stderr, "  - "+p)
			}
			return fmt.Errorf("triagecheck: %d 件の問題が見つかりました", len(problems))
		}
		fmt.Printf("triagecheck: 問題は見つかりませんでした（検査: review-file）\n")
		return nil
	}
	if *writeJudgmentFlow {
		// 判定フローの在り処が決まらないときは生成できない。検査の経路では「未導入
		// として通す」が、生成は明示の要求なので、書き出す先が無いことを報告する。
		if in.judgmentFlow == "" {
			return errJudgmentFlowRequired
		}
		return writeJudgmentFlowDiagram(in.judgmentFlow)
	}
	if *writeSummary {
		return writeReviewTriageSummaries(reviewTriageDir, true)
	}

	var problems []string
	recordFiles, err := listReviewTriageFiles(reviewTriageDir, true)
	if err != nil {
		// 不在は上で報告済みなので、ここに来るのは権限・I/O など、続行しても
		// 他の検査が意味を持たないエラーだけ。
		return fmt.Errorf("%s: 記録の一覧に失敗しました: %w", reviewTriageDir, err)
	}
	problems = append(problems, reviewTriageRecordProblems(recordFiles, os.ReadFile)...)
	problems = append(problems, judgmentFlowProblems(nil, os.ReadFile, in.judgmentFlowOrigin)...)

	if len(problems) > 0 {
		for _, p := range problems {
			fmt.Fprintln(os.Stderr, "  - "+p)
		}
		return fmt.Errorf("triagecheck: %d 件の問題が見つかりました", len(problems))
	}
	fmt.Printf("triagecheck: 問題は見つかりませんでした（検査: review-triage-record, judgment-flow）\n")
	return nil
}

